use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let n = input["n"].as_u64().unwrap();
    let start = input["start"].as_u64().unwrap();
    let edges = input["edges"].as_array().unwrap();
    let mut graph = vec![vec![]; n];
    for edge in edges {
        let from = edge[0].as_u64().unwrap();
        let to = edge[1].as_u64().unwrap();
        graph[from].push(to);
    }

    let mut queue = vec![start];
    let mut result = vec![];
    while let Some(node) = queue.pop() {
        result.push(node);
        for neighbor in &graph[node] {
            queue.push(neighbor);
        }
    }

    Value::Array(result.into_iter().map(|v| Value::Number(v.into())).collect())
}
